draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // ground
  ctx.fillStyle = '#964B00';
  ctx.fillRect(0, H - 20, W, 20);

  // character
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 20);
  ctx.lineTo(W / 2, H / 2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 50);
  ctx.lineTo(W / 2 - 20, H / 2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 50);
  ctx.lineTo(W / 2 + 20, H / 2 + 70);
  ctx.stroke();

  // event indicator
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('1898', W / 2 + Math.sin(t) * 20, H / 2 - 50);

  ctx.restore();
}
